/** Retry individual artwork failures without restarting the whole game. */
async function crossroadsDecodeImage(image) {
    const source = image.src;
    let cause;
    for (let attempt = 0; attempt < 3; attempt++) {
        let timer;
        try {
            if (attempt) {
                await new Promise(resolve => setTimeout(resolve, attempt * 500));
                const retry = new URL(source, document.baseURI);
                retry.searchParams.set('art-retry', String(attempt));
                image.src = retry.href;
            }
            await Promise.race([
                image.decode(),
                new Promise((_, reject) => {
                    timer = setTimeout(() => reject(new Error('Image load timed out')), 30000);
                }),
            ]);
            return;
        }
        catch (error) {
            cause = error;
            console.warn(`Artwork attempt ${attempt + 1}/3 failed: ${source}`, error);
        }
        finally {
            clearTimeout(timer);
        }
    }
    throw new Error(`Unable to load artwork after 3 attempts: ${source}`, { cause });
}

