/** Shop-local state never changes the player's game or equipped style during a preview. */
function createStyleShop() {
    let host, options, selected = '', row = 0, preview = false;
    let dispose = () => { };
    const columns = 2, visible = 6;
    function close() { dispose(); dispose = () => { }; preview = false; }
    function back() {
        if (!preview)
            return false;
        close();
        draw();
        host.querySelector('[data-shop-preview]')?.focus();
        return true;
    }
    function mount(target, next) {
        close();
        host = target;
        options = next;
        if (!next.styles.some(s => s.id === selected))
            selected = next.styles[0]?.id ?? '';
        row = Math.min(row, Math.max(0, Math.ceil((next.styles.length - visible) / columns)));
        draw();
    }
    function draw() {
        const style = options.styles.find(s => s.id === selected);
        if (!style)
            return;
        const maxRow = Math.max(0, Math.ceil((options.styles.length - visible) / columns));
        host.innerHTML = `<div class="sheet panel-sheet style-shop market-shop">
      <header class="shop-heading"><h2>Style Shop</h2><button class="btn shop-back" data-shop-back>Back</button></header>
      <div class="market-layout">
        <section class="shop-feature" aria-label="Selected style">
          <div class="shop-frame" style="--shop-frame:url('${style.frame}')"><img src="${style.image}" alt="${style.name}: 4 by 4 in-game map"></div>
          <h3>${style.name}</h3>
          <div class="shop-actions"><button class="btn" data-shop-preview>Preview</button><button class="btn primary" data-shop-equip ${options.busy || selected === options.equipped ? 'disabled' : ''}>${selected === options.equipped ? 'Equipped' : options.busy ? 'Loading…' : 'Equip'}</button></div>
        </section>
        <section class="shop-browser" aria-label="Styles">
          <button class="btn shop-arrow" data-shop-up aria-label="Previous row" ${row === 0 ? 'disabled' : ''}>▲</button>
          <div class="shop-collection">${options.styles.slice(row * columns, row * columns + visible).map(s => `<button class="shop-style${s.id === selected ? ' selected' : ''}" data-shop-style="${s.id}" data-style="${s.id}" aria-pressed="${s.id === selected}">
            <span class="shop-frame" style="--shop-frame:url('${s.frame}')"><img src="${s.image}" alt="" loading="lazy"></span><span class="shop-style-name">${s.name}</span>${s.id === options.equipped ? '<span class="shop-equipped">Equipped</span>' : ''}
          </button>`).join('')}</div>
          <button class="btn shop-arrow" data-shop-down aria-label="Next row" ${row >= maxRow ? 'disabled' : ''}>▼</button>
        </section>
      </div><p id="style-status" class="shop-status" role="status">${options.error}</p>
    </div>`;
        host.querySelector('[data-shop-back]')?.addEventListener('click', options.exit);
        host.querySelector('[data-shop-preview]')?.addEventListener('click', showPreview);
        host.querySelector('[data-shop-equip]')?.addEventListener('click', () => options.equip(selected));
        for (const button of host.querySelectorAll('[data-shop-style]'))
            button.onclick = () => {
                selected = button.dataset.shopStyle;
                draw();
                host.querySelector(`[data-shop-style="${selected}"]`)?.focus({ preventScroll: true });
            };
        for (const [selector, delta] of [['[data-shop-up]', -1], ['[data-shop-down]', 1]]) {
            host.querySelector(selector)?.addEventListener('click', () => {
                row = Math.max(0, Math.min(maxRow, row + delta));
                draw();
                host.querySelector(selector)?.focus({ preventScroll: true });
            });
        }
    }
    function showPreview() {
        dispose();
        preview = true;
        const style = options.styles.find(s => s.id === selected);
        const original = options.styles.find(s => s.id === 'minimal');
        host.innerHTML = `<div class="sheet panel-sheet style-shop shop-demo">
      <header class="shop-heading"><h2>${style.name}</h2><button class="btn shop-back" data-shop-back>Back</button></header>
      <div class="shop-compare-control"><span>Original</span><input type="range" min="0" max="100" value="50" aria-label="Compare Original and ${style.name}"><span>${style.name}</span></div>
      <div class="shop-film" style="--split:50%">
        <video class="shop-original" muted playsinline preload="auto" poster="${original.image}"></video>
        <div class="shop-selected-clip"><video class="shop-selected" muted playsinline preload="auto" poster="${style.image}"></video></div>
        <div class="shop-split" aria-hidden="true"></div>
      </div>
      <div class="shop-demo-controls"><button class="btn" data-shop-play disabled>Pause</button><button class="btn" data-shop-replay disabled>Replay</button><span class="shop-video-status" role="status">Loading…</span></div>
    </div>`;
        host.querySelector('[data-shop-back]')?.addEventListener('click', back);
        const film = host.querySelector('.shop-film');
        let zoom = 1, panX = 0, panY = 0;
        const wheel = (event) => {
            event.preventDefault();
            const rect = film.getBoundingClientRect();
            const x = (event.clientX - rect.left) / rect.width, y = (event.clientY - rect.top) / rect.height;
            const delta = event.deltaY * (event.deltaMode === 1 ? 16 : event.deltaMode === 2 ? rect.height : 1);
            const next = Math.min(4, Math.max(1, zoom * Math.exp(-delta * .0015)));
            panX = Math.min(0, Math.max(1 - next, x - (x - panX) * next / zoom));
            panY = Math.min(0, Math.max(1 - next, y - (y - panY) * next / zoom));
            zoom = next;
            film.style.setProperty('--zoom', String(zoom));
            film.style.setProperty('--pan-x', `${panX * 100}%`);
            film.style.setProperty('--pan-y', `${panY * 100}%`);
        };
        film.addEventListener('wheel', wheel, { passive: false });
        const slider = host.querySelector('input');
        slider.oninput = () => film.style.setProperty('--split', slider.value + '%');
        const a = host.querySelector('.shop-original'), b = host.querySelector('.shop-selected');
        const play = host.querySelector('[data-shop-play]'), replay = host.querySelector('[data-shop-replay]'), status = host.querySelector('.shop-video-status');
        let cancelled = false, playing = true, ready = false, timer = 0, restarting = false, pending = false, intent = 0;
        const pause = () => { a.pause(); b.pause(); };
        async function start() {
            if (cancelled || !ready || !playing || document.hidden || pending)
                return;
            const request = intent;
            pending = true;
            if (Math.abs(b.currentTime - a.currentTime) > .06)
                b.currentTime = a.currentTime;
            try {
                await Promise.all([a.play(), b.play()]);
                if (cancelled || !playing || document.hidden)
                    pause();
            }
            catch (error) {
                // A later Pause/Replay may abort this request. Never let its stale
                // rejection overwrite the user's latest Play/Pause intent.
                if (!cancelled && request === intent && error.name !== 'AbortError') {
                    pause();
                    playing = false;
                    play.textContent = 'Play';
                }
            }
            finally {
                pending = false;
                if (!cancelled && request !== intent && playing && !document.hidden)
                    void start();
            }
        }
        async function restart() {
            if (restarting || cancelled)
                return;
            restarting = true;
            intent++;
            pause();
            a.currentTime = b.currentTime = 0;
            if (playing)
                await start();
            restarting = false;
        }
        const loaded = () => {
            if (cancelled || ready || a.readyState < 3 || b.readyState < 3)
                return;
            ready = true;
            status.textContent = '';
            play.disabled = replay.disabled = false;
            void start();
        };
        const failed = () => { pause(); status.textContent = 'Preview unavailable. Try again.'; };
        for (const video of [a, b]) {
            video.oncanplay = loaded;
            video.onerror = failed;
        }
        a.onended = () => void restart();
        a.src = original.video;
        b.src = style.video;
        play.onclick = () => { intent++; playing = !playing; play.textContent = playing ? 'Pause' : 'Play'; if (playing)
            void start();
        else
            pause(); };
        replay.onclick = () => void restart();
        const visibility = () => { intent++; if (document.hidden)
            pause();
        else if (playing)
            void start(); };
        document.addEventListener('visibilitychange', visibility);
        timer = window.setInterval(() => {
            if (!ready || !playing || document.hidden || cancelled)
                return;
            if (a.readyState < 3 || b.readyState < 3) {
                if (!a.paused || !b.paused) {
                    intent++;
                    pause();
                }
                return;
            }
            if (Math.abs(a.currentTime - b.currentTime) > .06)
                b.currentTime = a.currentTime;
            if ((a.paused || b.paused) && !a.ended && !restarting)
                void start();
        }, 100);
        dispose = () => {
            cancelled = true;
            intent++;
            clearInterval(timer);
            document.removeEventListener('visibilitychange', visibility);
            film.removeEventListener('wheel', wheel);
            for (const video of [a, b]) {
                video.oncanplay = video.onerror = video.onended = null;
                video.pause();
                video.removeAttribute('src');
                video.load();
            }
        };
        host.querySelector('[data-shop-back]')?.focus();
    }
    return { mount, close, back };
}


const marketShop=createStyleShop();
